/**
 * Decision Log (ADR) — tool-local actions.
 *
 * Category: Risk & Governance (squad S5, Wave 2 — CRUD-backed tools)
 * Tool:     Architecture Decision Records (proposed → accepted →
 *           deprecated / superseded). One row per decision; the agent's
 *           usual ask is "what did we decide?" rather than "calculate me
 *           a score", so this file follows the DACI-shaped CRUD-backed
 *           pattern rather than the WSJF calculator pattern.
 *
 * Agent surface: tool.decision_log.*
 * Backing CRUD : workspace.decision.* (auto-generated by
 *                defineCrudActions in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (vs the calculator pattern) ────────────
 * Decisions are pure record-keeping entities. Generic create / list /
 * update / delete already exist via the auto-generated workspace.decision.*
 * surface, so this file only adds VERBS THE AGENT WANTS TO SPEAK in the
 * ADR domain vocabulary — things the generic CRUD surface can't express
 * without the agent constructing a full patch payload:
 *
 *   1. list_state       — read all decisions + summary stats (byStatus,
 *                         total). Lets the agent open with "what's the
 *                         state of architectural decisions?" without
 *                         paging through every row.
 *   2. set_status       — convenience over a workspace.decision.update
 *                         patch. Status is the single most-mutated field
 *                         in a decision's lifecycle and the agent
 *                         shouldn't have to marshal a {patch: {status: ...}}
 *                         object. Dynamically prompts ctx.confirm() when
 *                         transitioning to "deprecated"/"superseded"
 *                         (lifecycle-terminal states) because those edits
 *                         carry historical weight — an accidental
 *                         deprecation hides the decision from active
 *                         filters and the agent may not surface it again.
 *   3. supersede        — domain-specific lifecycle verb: marks the old
 *                         ADR status="superseded" AND links forward to
 *                         the replacing ADR via a consequences note. The
 *                         hand-equivalent — calling update twice and
 *                         remembering to append to consequences — was
 *                         hostile to agent UX. Idempotent if already
 *                         superseded by the same id.
 *   4. add_alternative  — idempotent append to alternatives[]. Saves the
 *                         agent from reading-then-merging and avoids
 *                         the array-overwrite bug a naive `update` patch
 *                         would cause when only `alternatives` changes.
 *
 * All write actions are `requiresConfirmation: false` statically.
 * `set_status` opts into a runtime `ctx.confirm` only for the two
 * lifecycle-terminal transitions (deprecated / superseded) — the
 * "point of no return" rule. The agent runtime supplies ctx.confirm
 * when running in approval mode; MCP and UI callers leave it undefined
 * and the handler assumes approval (consistent with how the rest of
 * the codebase reads ctx.confirm).
 *
 * ─── ID NAMING ───────────────────────────────────────────────────────
 * Namespace is `tool.decision_log` (snake_case; the user-facing route
 * slug is `/decision-log` with a hyphen, but action ids can't contain
 * hyphens because they get munged to underscores for the Anthropic
 * tool-name format anyway).
 *
 * Entity kind for serverGetEntity/serverUpsertEntity is
 * "workspace:decision" — matches kindFromToolId("workspace.decision")
 * used by the auto-generated CRUD in workspace/index.ts, so reads and
 * writes here line up byte-for-byte with the generic surface.
 * ─────────────────────────────────────────────────────────────────────
 */

import { z } from "zod";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverGetEntity, serverUpsertEntity } from "../server-store";
import type { Decision } from "@/lib/stores/workspace-types";

/** Server-side entity kind. Single-word entity, so kindFromToolId leaves
 *  the suffix untransformed and the server + browser-sync sides agree on
 *  "workspace:decision". */
const KIND_DECISION = "workspace:decision";

/** Closed enum of valid ADR lifecycle statuses. Matches the literal
 *  union in workspace-types.ts:Decision.status verbatim — Zod will
 *  reject anything else at the boundary. */
const STATUSES = ["proposed", "accepted", "deprecated", "superseded"] as const;
const StatusSchema = z.enum(STATUSES);

/** Lifecycle-terminal statuses that warrant a runtime confirm prompt
 *  when the in-app agent runtime supplies ctx.confirm. Deprecating or
 *  superseding an ADR hides it from active filters and discards the
 *  decision's authority — worth a click. */
const TERMINAL_STATUSES = new Set<Decision["status"]>(["deprecated", "superseded"]);

const ws = () => useWorkspaceStore.getState();

// ──────── tool.decision_log.list_state ────────
// Snapshot + summary stats. The agent's most common opening question
// for an ADR tool is "what decisions are on the books?" — returning the
// items array AND a byStatus breakdown in one round-trip avoids a
// follow-up reduce on the agent's end.
registry.register({
  id: "tool.decision_log.list_state",
  toolId: "tool.decision_log",
  name: "list_state",
  category: "read",
  description:
    "List all Architecture Decision Records (ADRs) in the workspace with a summary breakdown by status. Returns {total, byStatus: {proposed, accepted, deprecated, superseded}, items: Decision[]}.",
  paramsSchema: z.object({}),
  handler: async () => {
    const items = ws().decisions ?? [];
    return summarize(items);
  },
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<Decision>(ctx.userId, KIND_DECISION);
    return summarize(items);
  },
});

/** Build the {total, byStatus, items} response shape. Kept as a single
 *  helper so the browser-path and MCP-path responses are guaranteed
 *  identical — drift here would mean an agent gets different shapes
 *  depending on whether it's invoked from chat or over MCP. */
function summarize(items: Decision[]) {
  // Initialise every status key so the agent can index
  // byStatus.proposed without an existence check, even when the
  // workspace is empty.
  const byStatus: Record<Decision["status"], number> = {
    proposed: 0,
    accepted: 0,
    deprecated: 0,
    superseded: 0,
  };
  for (const d of items) {
    // Defensive: a hand-crafted entity with an out-of-enum status
    // would otherwise NaN the bucket (cf. the same guard in the
    // decision-log-client useMemo — same data, same defensive pose).
    // Skip silently — the items array still carries the row so the
    // agent can spot it if needed.
    if (d.status in byStatus) byStatus[d.status] += 1;
  }
  return { total: items.length, byStatus, items };
}

// ──────── tool.decision_log.set_status ────────
// Convenience over workspace.decision.update. Status is the single
// most-mutated property in an ADR's lifecycle (proposed → accepted;
// accepted → deprecated; accepted → superseded) and the generic update
// surface requires marshalling a full {patch: {status: ...}} payload.
//
// Calls ctx.confirm dynamically when transitioning to a terminal
// status (deprecated/superseded). Static requiresConfirmation stays
// false so non-terminal transitions don't pop a modal on every
// "mark accepted" — only the destructive lifecycle steps prompt.
//
// Returns {updated: boolean, confirmed?: boolean} — the latter is
// only present when a confirmation was requested, letting the agent
// distinguish "user denied" from "id not found".
registry.register({
  id: "tool.decision_log.set_status",
  toolId: "tool.decision_log",
  name: "set_status",
  category: "write",
  requiresConfirmation: false,
  description:
    "Update the status of an existing ADR (proposed | accepted | deprecated | superseded). Transitions to deprecated/superseded request runtime confirmation if the caller supplies ctx.confirm. Returns {updated: false} when the id is unknown.",
  paramsSchema: z.object({
    id: z.string(),
    status: StatusSchema,
  }),
  handler: async (params, ctx) => {
    const items = ws().decisions ?? [];
    const current = items.find((d) => d.id === params.id);
    if (!current) return { updated: false };
    if (TERMINAL_STATUSES.has(params.status) && ctx.confirm) {
      const ok = await ctx.confirm(
        `Mark ADR "${current.title || current.id}" as ${params.status}? This is a lifecycle-terminal transition.`
      );
      if (!ok) return { updated: false, confirmed: false };
    }
    ws().upsertDecision({ ...current, status: params.status });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<Decision>(ctx.userId, KIND_DECISION, params.id);
    if (!current) return { updated: false };
    if (TERMINAL_STATUSES.has(params.status) && ctx.confirm) {
      const ok = await ctx.confirm(
        `Mark ADR "${current.title || current.id}" as ${params.status}? This is a lifecycle-terminal transition.`
      );
      if (!ok) return { updated: false, confirmed: false };
    }
    await serverUpsertEntity<Decision>(ctx.userId, KIND_DECISION, {
      ...current,
      status: params.status,
    });
    return { updated: true };
  },
});

// ──────── tool.decision_log.supersede ────────
// Lifecycle verb: mark the old ADR as superseded AND append a forward
// reference into its consequences so a reader following the trail
// finds the replacing ADR without having to grep.
//
// Idempotent: if the decision is already status="superseded" AND its
// consequences already mention `supersededBy`, returns {superseded:
// false, alreadySuperseded: true} and skips the write. This matters
// when an agent retries on a transient error — we don't want to
// double-append the link.
//
// Returns {superseded: false, reason: "not_found"} when the id is
// unknown so the agent can detect missing-id without throwing.
registry.register({
  id: "tool.decision_log.supersede",
  toolId: "tool.decision_log",
  name: "supersede",
  category: "write",
  requiresConfirmation: false,
  description:
    "Mark an existing ADR as superseded by another ADR. Sets status='superseded' and appends a forward-reference note to consequences. Idempotent if the same supersedure has already been recorded. Returns {superseded: false} on missing id or no-op.",
  paramsSchema: z.object({
    id: z.string().describe("Id of the ADR being superseded (the old one)"),
    supersededBy: z.string().describe("Id of the replacing ADR (the new one)"),
    reason: z
      .string()
      .optional()
      .describe("Optional human-readable note for the consequences trail"),
  }),
  handler: async (params) => {
    const items = ws().decisions ?? [];
    const current = items.find((d) => d.id === params.id);
    if (!current) return { superseded: false, reason: "not_found" as const };
    const next = applySupersede(current, params.supersededBy, params.reason);
    if (!next) return { superseded: false, alreadySuperseded: true };
    ws().upsertDecision(next);
    return { superseded: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<Decision>(ctx.userId, KIND_DECISION, params.id);
    if (!current) return { superseded: false, reason: "not_found" as const };
    const next = applySupersede(current, params.supersededBy, params.reason);
    if (!next) return { superseded: false, alreadySuperseded: true };
    await serverUpsertEntity<Decision>(ctx.userId, KIND_DECISION, next);
    return { superseded: true };
  },
});

/** Pure builder: compute the post-supersede shape of a decision, or
 *  null if no change is required (already terminal & link present).
 *  Extracted so both handlers share the exact idempotency check —
 *  drift here would mean the browser path and the MCP path could
 *  disagree about whether a retry is a no-op. */
function applySupersede(current: Decision, supersededBy: string, reason?: string): Decision | null {
  const existingConsequences = current.consequences ?? "";
  // Stable marker the idempotency check can grep for. Includes the
  // target id so two distinct supersedure links (rare but legal:
  // re-superseded by yet another ADR later) don't collapse together.
  const marker = `Superseded by ${supersededBy}`;
  const alreadyLinked = existingConsequences.includes(marker);
  if (current.status === "superseded" && alreadyLinked) {
    return null;
  }
  // Build the note. Two-line block so it visually separates from
  // any prior consequences prose without smashing the existing text.
  const note = reason ? `${marker}. ${reason}` : marker;
  const nextConsequences = alreadyLinked
    ? existingConsequences
    : existingConsequences
      ? `${existingConsequences}\n\n${note}`
      : note;
  return {
    ...current,
    status: "superseded",
    consequences: nextConsequences,
  };
}

// ──────── tool.decision_log.add_alternative ────────
// Idempotent append to alternatives[]. Read-modify-write through the
// store / server so a concurrent agent call that already added the
// same alternative won't produce duplicate entries. Returns
// {added: boolean} — false when the alternative was already present
// OR the decision is missing.
registry.register({
  id: "tool.decision_log.add_alternative",
  toolId: "tool.decision_log",
  name: "add_alternative",
  category: "write",
  requiresConfirmation: false,
  description:
    "Append a string to the alternatives[] of an existing ADR. Idempotent — skips if the alternative is already present. Returns {added: false} when the id is unknown OR the alternative was already there.",
  paramsSchema: z.object({
    id: z.string(),
    alternative: z.string().min(1).max(500),
  }),
  handler: async (params) => {
    const items = ws().decisions ?? [];
    const current = items.find((d) => d.id === params.id);
    if (!current) return { added: false };
    const existing = current.alternatives ?? [];
    if (existing.includes(params.alternative)) return { added: false };
    ws().upsertDecision({
      ...current,
      alternatives: [...existing, params.alternative],
    });
    return { added: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<Decision>(ctx.userId, KIND_DECISION, params.id);
    if (!current) return { added: false };
    const existing = current.alternatives ?? [];
    if (existing.includes(params.alternative)) return { added: false };
    await serverUpsertEntity<Decision>(ctx.userId, KIND_DECISION, {
      ...current,
      alternatives: [...existing, params.alternative],
    });
    return { added: true };
  },
});
